import{z as B,x as C,o as a,c as o,q as i,j as r,D as E,d as e,s as l,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"MAC 与签名","description":"","frontmatter":{"title":"MAC 与签名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mac-signature.md","filePath":"cs/mac-signature.md","lastUpdated":1791413859000}'),p={name:"cs/mac-signature.md"};function d(m,A,c,D,M,h){const t=C("Mermaid");return a(),o("div",null,[A[2]||(A[2]=i('<h1 id="mac-与签名" tabindex="-1">MAC 与签名 <a class="header-anchor" href="#mac-与签名" aria-label="Permalink to &quot;MAC 与签名&quot;">​</a></h1><div class="epigraph"><p>MAC 证明「持有共享密钥的人认过这份字节」；签名证明「持有私钥的人认过」，且第三人可验。</p><footer>—— 据 Goldwasser, Micali and Rivest 对签名方案；HMAC 作为 MAC 的工程标准整理</footer></div><p><a href="/cs/hash-collision">上一课</a>给出抗碰撞哈希。本课不重证生日界。缺口是：完整与认证——谁能声称这段字节没被改、出自谁。共享密钥用 MAC；公钥侧用数字签名。两者都常先哈希再认证，但密钥用法与能否公开验证不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AEAD 已能在对称会话里绑完整。许多场景要单独的认证标签，或要<strong>不可否认</strong>：验证方没有签名私钥，不能自己伪造，却能向第三方证明。缺口不是再讲加密，而是两条原语：MAC（对称、不可公开转述为「只有某一人能做」）、签名（私钥签、公钥验）。</p><p><span class="marginnote">裸 \\(H(k\\|m)\\) 有长度扩展等问题；HMAC 把密钥与哈希组合成标准 MAC。签名则对 \\(H(m)\\) 做私钥运算，证书把公钥绑到名字。</span></p><p><span class="marginnote">术语翻译：「不可否认」就是事后赖不了账。签名由私钥生成，任何拿到公钥的人都能复验；签名者无法声称「标签是验证者自己造的」，因为他根本没有那把私钥。MAC 做不到：验证者手里的共享密钥同样能造出合法标签。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MAC：输入密钥与消息，输出标签；验证即重算比较（常数时间比较，避免泄长度以外的信息——侧信道课再收）。签名：Sign\\((sk,m)\\)、Verify\\((pk,\\sigma,m)\\)。本课不选 RSA-PSS 还是 ECDSA 曲线，只锁定接口与失败含义：标签错或验签失败 ⇒ 不接受，至于是改包还是密钥错，协议层要另处理。</p>',9)),(a(),r(n,null,{default:E(()=>[l(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HASH%5B%22%E6%91%98%E8%A6%81%20H(m)%22%5D%20--%3E%20MAC%5B%22MAC%3A%20%E5%85%B1%E4%BA%AB%E9%94%AE%22%5D%0A%20%20HASH%20--%3E%20SIG%5B%22%E7%AD%BE%E5%90%8D%3A%20%E7%A7%81%E9%92%A5%22%5D%0A%20%20SIG%20--%3E%20CERT%5B%22%E5%90%8E%E8%AF%BE%3A%20%E8%AF%81%E4%B9%A6%E4%B8%8E%20PKI%22%5D%0A%20%20MAC%20--%3E%20CERT%0A"})]),fallback:E(()=>[...A[0]||(A[0]=[e(" Loading... ",-1)])]),_:1})),A[3]||(A[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),A[4]||(A[4]=s("p",null,"MAC 服务 CIA 的 I 与真实性（在共享密钥团体内）。签名另加不可否认与公开验证，供证书链、软件更新、2PC 之外的「这个字节来自哪一身份」。密钥泄露模型不同：MAC 密钥泄露使双方都能伪造；签名私钥泄露使全世界都能冒充，直到撤销。",-1)),(a(),r(n,null,{default:E(()=>[l(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSG%5B%22%E6%94%B6%E5%88%B0%20%E6%B6%88%E6%81%AF%E4%B8%8E%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20GOAL%7B%22%E9%AA%8C%E8%AF%81%E8%80%85%E6%83%B3%E5%90%91%E7%AC%AC%E4%B8%89%E6%96%B9%E8%AF%81%E6%98%8E%E5%87%BA%E5%A4%84%22%7D%0A%20%20GOAL%20--%3E%20MACP%5B%22MAC%20%E6%96%B9%E6%A1%88%3A%20%E9%AA%8C%E8%AF%81%E8%80%85%E6%8C%81%E6%9C%89%E5%90%8C%E4%B8%80%E5%85%B1%E4%BA%AB%E5%AF%86%E9%92%A5%22%5D%0A%20%20MACP%20--%3E%20MC%5B%22%E7%AC%AC%E4%B8%89%E6%96%B9%E6%97%A0%E6%B3%95%E5%8C%BA%E5%88%86%E6%A0%87%E7%AD%BE%E5%87%BA%E8%87%AA%E8%B0%81%3A%20%E9%AA%8C%E8%AF%81%E8%80%85%E6%9C%AC%E4%BA%BA%E4%B9%9F%E9%80%A0%E5%BE%97%E5%87%BA%22%5D%0A%20%20MC%20--%3E%20NREP%5B%22%E4%B8%8D%E5%8F%AF%E5%90%A6%E8%AE%A4%E7%BC%BA%E5%B8%AD%2C%20%E4%B8%8D%E8%83%BD%E5%BD%93%E8%AF%81%E6%8D%AE%22%5D%0A%20%20GOAL%20--%3E%20SIGP%5B%22%E7%AD%BE%E5%90%8D%E6%96%B9%E6%A1%88%3A%20%E9%AA%8C%E8%AF%81%E8%80%85%E5%8F%AA%E6%9C%89%E5%85%AC%E9%92%A5%22%5D%0A%20%20SIGP%20--%3E%20SC%5B%22%E7%A7%81%E9%92%A5%E5%8F%AA%E5%9C%A8%E7%AD%BE%E5%90%8D%E8%80%85%E6%89%8B%E9%87%8C%3A%20%E7%AC%AC%E4%B8%89%E6%96%B9%E5%8F%AF%E7%94%A8%E5%85%AC%E9%92%A5%E5%A4%8D%E9%AA%8C%22%5D%0A%20%20SC%20--%3E%20ATTR%5B%22%E5%8F%AF%E5%BD%92%E8%B4%A3%E4%BA%8E%E6%8C%81%E9%92%A5%E8%BA%AB%E4%BB%BD%22%5D%0A"})]),fallback:E(()=>[...A[1]||(A[1]=[e(" Loading... ",-1)])]),_:1})),A[5]||(A[5]=i('<p><span class="marginnote">直觉类比：MAC 像合租公寓的备用钥匙——你和室友都能开门，丢了东西说不清是谁进的；签名像只有你有指纹的私章，谁拿到章盒（公钥）都能验指纹，但章只有你能盖。</span></p><p>常数时间比较标签，避免把比较提前返回当成侧信道；细节在侧信道课。</p><p><span class="marginnote">数字实例：逐字节提前返回的比较，错在第 1 字节和错在第 32 字节耗时不同，攻击者按耗时逐位「摸」出正确标签；改成把 32 字节全部异或累加、最后比一次，耗时与错几位无关，信道就关上了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>签名不是加密。加密的保密与签名的公开可验证可以组合（先签后封或相反），顺序有规范，本课不把每一种 CMS 变体写完。也不把「区块链签名」插入主干。时间戳、公证是额外服务。</p><p>MAC 不能转给第三方当证据：验证者自己也能造同一标签。这是不可否认缺席的精确定义。后课默认：完整性标签要么是 MAC/AEAD，要么是签名；名字如何绑到公钥，是 PKI。</p><p>验证失败应失败安全：不接受，不「尽量解密」。这与 Saltzer 的失败安全默认是同一句，对象换成标签。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>密钥泄露模型不同：MAC 团体内都能伪，签名私钥泄露则人人能冒充直到撤销。</p></li><li><p>后课证书把 \\(pk\\) 绑到名字，否则签名只证明「某把私钥」。</p></li><li><p>哈希是零件；MAC 用共享键认证，签名可公开验证。</p></li><li><p>不可否认是签名相对 MAC 的差额，不是更长的摘要。</p></li><li><p>公钥如何被相信属于某个名字，是证书课缺口。</p></li><li><p>出处：Goldwasser, Micali and Rivest；RFC 2104 HMAC；Stallings。</p></li></ul>',9))])}const _=B(p,[["render",d]]);export{u as __pageData,_ as default};
